package resizable

props {
  // Orientation sets the direction of the panels: Horizontal or Vertical.
  Orientation Orientation = Horizontal
  // Class adds classes to the root element.
  Class       string = ""
  // Children are the panels, with one ResizableHandle between two panels.
  Children    gx.Node
  // Attrs adds HTML attributes to the root element.
  Attrs       gx.Attrs = nil
}

<div data-slot="resizable-panel-group" data-orientation={p.orientation()} class={gx.Cx(groupClass[p.orientation()], p.Class)} {...p.Attrs}>{p.Children}</div>

package resizable

props {
  // Size is the first size of the panel, in percent of the group. A zero value shares the free space.
  Size     int = 0
  // MinSize is the smallest size of the panel, in percent of the group.
  MinSize  int = 0
  // MaxSize is the largest size of the panel, in percent of the group. A zero value is 100.
  MaxSize  int = 0
  // Class adds classes to the content element inside the panel.
  Class    string = ""
  // Children is the content of the panel.
  Children gx.Node
  // Attrs adds HTML attributes to the root element.
  Attrs    gx.Attrs = nil
}

<div data-slot="resizable-panel" data-min-size={p.MinSize} data-max-size={p.maxSize()} style={p.style()} class={panelClass} {...p.Attrs}>
  <div class={gx.Cx(contentClass, p.Class)}>{p.Children}</div>
</div>

package resizable

props {
  // Id is the id of the handle.
  Id          string
  // Label is the accessible name of the handle.
  Label       string = "Resize panels"
  // Orientation is the direction of the panel group: Horizontal or Vertical.
  Orientation Orientation = Horizontal
  // Step is the size of one arrow key step, in percent of the group. A zero value is 5.
  Step        int = 5
  // Class adds classes to the root element.
  Class       string = ""
  // Attrs adds HTML attributes to the root element.
  Attrs       gx.Attrs = nil
}

<div id={p.Id} role="separator" tabindex="0" aria-label={p.label()} aria-orientation={p.ariaOrientation()} aria-valuenow="50" aria-valuemin="0" aria-valuemax="100" data-slot="resizable-handle" class={gx.Cx(handleClass[p.orientation()], p.Class)} {...p.Attrs}>
  <ResizableDrag handle={p.Id} step={p.step()} gripClass={gripClass[p.orientation()]} load="eager" />
</div>

